content:
return false;

      return entry->data.markIndex != 0xFFFF || entry->data.currentIndex != 0xFFFF;
    }
    inline bool transition (StateTableDriver<EntryData> *driver,
                            const Entry<EntryData> *entry)
    {
      hb_buffer_t *buffer = driver->buffer;

      /* Looks like CoreText applies neither mark nor current substitution for
       * end-of-text if mark was not explicitly set. */
      if (buffer->idx == buffer->len && !mark_set)
        return true;

      if (entry->data.markIndex != 0xFFFF)
      {
        const Lookup<GlyphID> &lookup = subs[entry->data.markIndex];
        hb_glyph_info_t *info = buffer->info;
        const GlyphID *replacement = lookup.get_value (info[mark].codepoint, driver->num_glyphs);
        if (replacement)
        {
          buffer->unsafe_to_break (mark, MIN (buffer->idx + 1, buffer->len));
          info[mark].codepoint = *replacement;
          ret = true;
        }
      }
      if (entry->data.currentIndex != 0xFFFF)
      {
        unsigned int idx = MIN (buffer->idx, buffer->len - 1);
        const Lookup<GlyphID> &lookup = subs[entry->data.currentIndex];
        hb_glyph_info_t *info = buffer->info;
        const GlyphID *replacement = lookup.get_value (info[idx].codepoint, driver->num_glyphs);
        if (replacement)
        {
          info[idx].codepoint = *replacement;
          ret = true;
        }
      }

      if (entry->flags & SetMark)
      {
        mark_set = true;
        mark = buffer->idx;
      }

      return true;
    }

    public:
    bool ret;
    private:
    bool mark_set;
    unsigned int mark;
    const UnsizedOffsetListOf<Lookup<GlyphID>, HBUINT32> &subs;
  };

  inline bool apply (hb_aat_apply_context_t *c) const
  {
    TRACE_APPLY (this);

    driver_context_t dc (this);

    StateTableDriver<EntryData> driver (machine, c->buffer, c->face);
    driver.drive (&dc);

    return_trace (dc.ret);
  }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);

    unsigned int num_entries = 0;
    if (unlikely (!machine.sanitize (c, &num_entries))) return_trace (false);

    unsigned int num_lookups = 0;

    const Entry<EntryData> *entries = machine.get_entries ();
    for (unsigned int i = 0; i < num_entries; i++)
    {
      const EntryData &data = entries[i].data;

      if (data.markIndex != 0xFFFF)
        num_lookups = MAX<unsigned int> (num_lookups, 1 + data.markIndex);
      if (data.currentIndex != 0xFFFF)
        num_lookups = MAX<unsigned int> (num_lookups, 1 + data.currentIndex);
    }

    return_trace (substitutionTables.sanitize (c, this, num_lookups));
  }

  protected:
  StateTable<EntryData>
                machine;
  LOffsetTo<UnsizedOffsetListOf<Lookup<GlyphID>, HBUINT32>, false>
                substitutionTables;
  public:
  DEFINE_SIZE_STATIC (20);
};

struct LigatureSubtable
{
  struct EntryData
  {
    HBUINT16    ligActionIndex; /* Index to the first ligActionTable entry
                                 * for processing this group, if indicated
                                 * by the flags. */
    public:
    DEFINE_SIZE_STATIC (2);
  };

  struct driver_context_t
  {
    static const bool in_place = false;
    enum Flags
    {
      SetComponent      = 0x8000,       /* Push this glyph onto the component stack for
                                         * eventual processing. */
      DontAdvance       = 0x4000,       /* Leave the glyph pointer at this glyph for the
                                           next iteration. */
      PerformAction     = 0x2000,       /* Use the ligActionIndex to process a ligature
                                         * group. */
      Reserved          = 0x1FFF,       /* These bits are reserved and should be set to 0. */
    };
    enum LigActionFlags
    {
      LigActionLast     = 0x80000000,   /* This is the last action in the list. This also
                                         * implies storage. */
      LigActionStore    = 0x40000000,   /* Store the ligature at the current cumulated index
                                         * in the ligature table in place of the marked
                                         * (i.e. currently-popped) glyph. */
      LigActionOffset   = 0x3FFFFFFF,   /* A 30-bit value which is sign-extended to 32-bits
                                         * and added to the glyph ID, resulting in an index
                                         * into the component table. */
    };

    inline driver_context_t (const LigatureSubtable *table,
                             hb_aat_apply_context_t *c_) :
        ret (false),
        c (c_),
        ligAction (table+table->ligAction),
        component (table+table->component),
        ligature (table+table->ligature),
        match_length (0) {}

